using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "MeissaBattleCustomEventSetup", menuName = "Data/BattleSceneSetups/MeissaBattleCustomEventSetup", order = 0)]
public class MeissaBattleCustomEventSetup : CustomEventSetup
{
	[Header("Meissa Battle Handler")]
	[SerializeField]
	private GameObject meissaBattleHandler;

	[SerializeField]
	private MapHandler mapHandler;

	[SerializeField]
	private ClearingReward meissaBattleFakeClearingReward;

	public override void SetupScene()
	{
		mapHandler.SetClearingReward(meissaBattleFakeClearingReward, goToEndOfBattleState: false);
		mapHandler.ResetCurrentRewardCounter();
		base.SetupScene();
		Object.Instantiate(meissaBattleHandler);
	}
}
